import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
		// your code goes here
		static int n;
		static long[] pref;
		
		static long getStrength(int k1, int k2){
		    int end6 = k1;
		    int end4 = k1 + 2 * k2;
		    int end3 = 3*n-(2 * k1 + k2);
		    
		    
		    long sum6 = pref[end6];
		    long sum4 = pref[end4] - pref[end6];
		    long sum3 = pref[end3] - pref[end4];
		    return 6* sum6 + 4 * sum4 + 3 * sum3;
}

    public static void main(String[] args) throws java.lang.Exception{
        Scanner sc = new Scanner(System.in);
        
        if(!sc.hasNextInt()) return;
        
        int T = sc.nextInt();
        while(T --> 0){
            n = sc.nextInt();
            
            int Total = 3 * n;
            long[] arr = new long[Total];
            
            for(int i = 0; i < Total; i++){
                arr[i] = sc.nextLong();
            }
            Arrays.sort(arr);
            
            long[] a = new long[Total + 1];
            
            for(int i = 0; i < Total; i++){
                a[i+1] = arr[Total-1-i];
            }
            
            pref = new long[Total+1];
            
            for(int i = 1; i <= Total; i++){
                pref[i] = pref[i-1] + a[i];
            }
            
            long Max = 0;
            for(int k1 = 0; k1 <= n; k1++){
                int low = 0;
                int high = n - k1;
                
                while(high - low >= 3){
                    int m1 = low + (high - low)/3;
                    int m2 = high - (high-low) /3;
                    if(getStrength(k1,m1) < getStrength(k1,m2)){
                        low = m1;
                    }
                    else{
                        high = m2;
                    }
                }
                for(int k2 = low; k2 <= high; k2++){
                    Max = Math.max(Max,getStrength(k1,k2));
                }
            }
            System.out.println(Max);
        }
    }
}
